use super::*;
use crate::money::{money, sum, Money};

/// What one tier costs over `months` months — the annual framing.
pub fn over_window(v: &ViableIncome, t: &TierRequirement, months: usize) -> Money {
    let each = vec![t.typical_month; months];
    sum(&each, v.currency).unwrap_or_else(|_| money(0, v.currency))
}
